<template>
  <div class="providers-page"><header class="page-head"><div><span class="eyebrow">系统 / 上游管理</span><h2>供应商与模型</h2><p>查看上游连接状态、模型数量和启用情况。密钥编辑仍统一从供应商配置入口进入。</p></div><t-button variant="outline" :loading="loading" @click="load"><template #icon><t-icon name="refresh" /></template>刷新</t-button></header><div class="provider-grid"><article v-for="vendor in vendors" :key="vendor.id" class="provider-card"><div class="provider-head"><div class="provider-logo">{{initial(vendor.name||vendor.id)}}</div><div><h3>{{vendor.name||vendor.id}}</h3><small>{{vendor.id}}</small></div><span :class="['status',vendor.enable?'on':'off']"><i></i>{{vendor.enable?'已启用':'已停用'}}</span></div><p>{{vendor.description||'未填写供应商说明'}}</p><div class="provider-meta"><span>{{(vendor.models||[]).length}} 个模型</span><span>{{vendor.author||'XOi'}}</span><span>{{vendor.credentialsConfigured?'已配置凭据':'待配置'}}</span></div><div class="provider-actions"><t-button size="small" variant="outline" :loading="pending.has(vendor.id)" @click="toggle(vendor)">{{vendor.enable?'停用供应商':'启用供应商'}}</t-button><t-button size="small" theme="primary" variant="text" @click="goSettings">编辑配置 →</t-button></div></article></div><t-empty v-if="!loading&&!vendors.length" description="暂无供应商" /></div>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import axios from '@/utils/axios'; import settingStore from '@/stores/setting';
const pending = ref(new Set<string>());
const vendors=ref<any[]>([]),loading=ref(false),store=settingStore();function initial(v:string){return(v||'?').trim().charAt(0).toUpperCase()}async function load(){loading.value=true;try{const res=await axios.post('/setting/vendorConfig/getVendorList');vendors.value=(res.data||[]).map((v:any)=>({...v,inputValues:v.inputValues||{}}));}catch(e:any){window.$message?.error?.(e.message||'供应商加载失败')}finally{loading.value=false}}async function toggle(v:any){if(pending.value.has(v.id))return;pending.value.add(v.id);try{await axios.post('/setting/vendorConfig/enableVendor',{id:v.id,enable:v.enable?0:1});v.enable=v.enable?0:1;window.$message?.success?.(v.enable?'供应商已启用':'供应商已停用')}catch(e:any){window.$message?.error?.(e.message||'状态更新失败')}finally{pending.value.delete(v.id)}}function goSettings(){store.activeMenu='vendorConfig';store.showSetting=true}onMounted(load);
</script>
<style scoped lang="scss">
.providers-page{padding:28px 32px 38px;color:#152238}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:22px}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.12em;color:#ef6c35}.page-head h2{margin:8px 0 5px;font-size:25px}.page-head p{margin:0;color:#8993a5;font-size:13px}.provider-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px}.provider-card{padding:18px;border:1px solid #e8ebf1;border-radius:17px;background:#fff;box-shadow:0 8px 25px rgba(31,45,72,.04)}.provider-head{display:flex;align-items:center;gap:10px}.provider-logo{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,#7775d8,#ee8a6a);color:#fff;font-weight:800}.provider-head h3{margin:0;font-size:14px}.provider-head small{color:#98a1b1;font-size:10px}.status{display:inline-flex;align-items:center;gap:5px;margin-left:auto;font-size:10px}.status i{width:6px;height:6px;border-radius:50%}.status.on{color:#159a67}.status.on i{background:#1eaf73}.status.off{color:#a16c72}.status.off i{background:#d38a94}.provider-card>p{min-height:34px;margin:15px 0;color:#7e8999;font-size:12px;line-height:1.6}.provider-meta{display:flex;gap:9px;flex-wrap:wrap;color:#68758a;font-size:10px}.provider-meta span{padding:5px 7px;border-radius:7px;background:#f5f7fa}.provider-actions{display:flex;justify-content:space-between;align-items:center;margin-top:16px;padding-top:13px;border-top:1px solid #eef0f4}
</style>
